// @generated by `distributed game-client` from game surface `grid` (schema v3, protocol v1).
// Pure functions: the Rust `#[game_pure]` fns compiled to WebAssembly (binary ABI).
// Do not edit: change the Rust definitions and regenerate.
import { createWasmPures, type WasmPures, type WasmSource, type WireType } from '@hops-ops/distributed/game';

import type { GridCellContent, GridContext, GridPoint, GridSample } from './events.ts';

const PROP_TYPE: WireType = {
	type: 'record',
	fields: [
		['kind', { type: 'u8' }],
		['x', { type: 'f32' }],
		['y', { type: 'f32' }],
		['r', { type: 'f32' }],
		['solid', { type: 'bool' }],
		['variant', { type: 'u8' }],
	]
};

const GRID_CELL_CONTENT_TYPE: WireType = {
	type: 'record',
	fields: [
		['heights', { type: 'list', item: { type: 'f32' } }],
		['moisture', { type: 'list', item: { type: 'f32' } }],
		['biomes', { type: 'bytes' }],
		['props', { type: 'list', item: PROP_TYPE }],
	]
};

const GRID_CONTEXT_TYPE: WireType = {
	type: 'record',
	fields: [
		['seed', { type: 'u32' }],
		['cx', { type: 'i32' }],
		['cy', { type: 'i32' }],
	]
};

const GRID_POINT_TYPE: WireType = {
	type: 'record',
	fields: [
		['seed', { type: 'u32' }],
		['cx', { type: 'i32' }],
		['cy', { type: 'i32' }],
		['x', { type: 'f32' }],
		['y', { type: 'f32' }],
	]
};

const GRID_SAMPLE_TYPE: WireType = {
	type: 'record',
	fields: [
		['height', { type: 'f32' }],
		['moisture', { type: 'f32' }],
		['biome', { type: 'u8' }],
	]
};

/** The pure functions (`#[game_pure]`) of Cargo package `game_sim`: wrapper name → module export. */
export const PURES = {
	gridCell: { export: 'grid_cell', abi: 1 },
	gridSample: { export: 'grid_sample', abi: 1 },
} as const;

/** The compiled module (`distributed game-wasm`; shared with the predicted step); bundlers emit it as an asset. */
export const PURES_WASM_URL: URL = new URL('./wasm/grid.wasm', import.meta.url);

/** Typed calls of the compiled functions (synchronous; they throw until `ready` resolves). */
export interface GridPureFns {
	/** `grid_cell` (`dg_pure_grid_cell`). */
	gridCell(arg: GridContext): GridCellContent;
	/** `grid_sample` (`dg_pure_grid_sample`). */
	gridSample(arg: GridPoint): GridSample;
}

/** The `grid` pure functions plus `ready` / `loaded()` / `module()`. */
export type GridPures = WasmPures<GridPureFns>;

/**
 * Load the compiled pure functions (default `PURES_WASM_URL`; a URL loaded by
 * the predicted step too is instantiated once).
 */
export function createGridPures(source: WasmSource = PURES_WASM_URL): GridPures {
	return createWasmPures<GridPureFns>(source, {
		gridCell: { exportName: 'grid_cell', arg: GRID_CONTEXT_TYPE, output: GRID_CELL_CONTENT_TYPE },
		gridSample: { exportName: 'grid_sample', arg: GRID_POINT_TYPE, output: GRID_SAMPLE_TYPE },
	});
}
